/* converted header/footer styles */
.footer .site-title-text,.footer .site-logo__eyebrow,.footer .site-logo__sub{color:rgb(156, 163, 175) !important}
.footer .site-logo__mark:not(.site-logo__mark--framed){color:rgb(156, 163, 175) !important}
